head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > useMonthYearFormat]<br/>dataType=date 이고 바인딩 되었을때 yyyyMMdd 로 데이터 포맷을 고정시킬지 설정합니다.",
    "validation" : [
        "미설정 시 DataCollection 과 바인딩 되었을때 DataCollection 과 바인딩 되었을때 ioFormat 속성에 설정된 포맷으로 데이터를 주고 받습니다.",
        "true 설정 시 DataCollection 과 바인딩 되었을때 yyyyMMdd 포맷으로 데이터를 주고 받습니다.",
        "false 설정 시 DataCollection 과 바인딩 되었을때 DataCollection 과 바인딩 되었을때 ioFormat 속성에 설정된 포맷으로 데이터를 주고 받습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
};


scwin.btn_getBindData1_onclick = function (e) {
    let rtn = ''
    rtn = dm_ref1.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue("get bindData : " + rtn);
};


// target2
scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
};


scwin.btn_getBindData2_onclick = function (e) {
    let rtn = ''
    rtn = dm_ref2.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue("get bindData : " + rtn);
